static void bind(PharaohMonumentWorkSpotBinding *out,
    const struct SpotBindingSpec *spec, uint32_t count,
    PharaohMonumentSpotAnimation *spots)
{
    for (uint32_t i=0; i<count; ++i) {
        memcpy(out[i].reserved_00, spec[i].reserved, 8);
        out[i].spot = &spots[spec[i].spot];
        out[i].initial_work_remaining = spec[i].work;
    }
}

void pharaoh_monument_scene_data_initialize(PharaohMonumentSceneData *data,
    PharaohMonumentSpotAnimation *const spots[9])
{
    memcpy(spots[0], initial_small_obelisk, sizeof(initial_small_obelisk));
    bind(data->small_obelisk, small_obelisk_bindings, 10, spots[0]);
    memcpy(spots[1], initial_large_obelisk, sizeof(initial_large_obelisk));
    bind(data->large_obelisk, large_obelisk_bindings, 18, spots[1]);
    memcpy(spots[2], initial_sphinx, sizeof(initial_sphinx));
    bind(data->sphinx, sphinx_bindings, 22, spots[2]);
    memcpy(spots[3], initial_sun_temple, sizeof(initial_sun_temple));
    bind(data->sun_temple, sun_temple_bindings, 13, spots[3]);
    memcpy(spots[4], initial_library, sizeof(initial_library));
    bind(data->library, library_bindings, 27, spots[4]);
    memcpy(spots[5], initial_abu_simbel, sizeof(initial_abu_simbel));
    bind(data->abu_simbel, abu_simbel_bindings, 56, spots[5]);
    memcpy(spots[6], initial_caesareum, sizeof(initial_caesareum));
    bind(data->caesareum, caesareum_bindings, 27, spots[6]);
    memcpy(spots[7], initial_lighthouse, sizeof(initial_lighthouse));
    bind(data->lighthouse, lighthouse_bindings, 15, spots[7]);
    memcpy(spots[8], initial_royal_tomb, sizeof(initial_royal_tomb));
    bind(data->royal_tomb, royal_tomb_bindings, 75, spots[8]);
    static const uint8_t groups[25] = {0,3,6,36,39,9,12,15,18,42,45,21,24,57,48,60,63,27,30,33,51,54,66,69,72};
    for (uint32_t i=0; i<25; ++i) {
        data->royal_groups[i].bindings = &data->royal_tomb[groups[i]];
        data->royal_groups[i].initial_work_override =
            i == 4 ? &data->royal_tomb[6] : NULL;
    }
}
